'[{"sound":"Silent t in restaurant","ipa":"/ˈrestərɑːnt/","tips":"The second t is often silent","examples":["restaurant /ˈrestərɑːnt/"]},{"sound":"ch sound","ipa":"/tʃ/","tips":"Like chair","examples":["check /tʃek/","chicken /ˈtʃɪkɪn/"]},{"sound":"Word stress","ipa":"Emphasis","tips":"Stress on third syllable","examples":["res-er-VA-tion","AP-pe-ti-zer"]}]',
