-- Lição 4: Na Escola  
INSERT INTO lessons (id, courseId, title, description, orderIndex, languageCode, estimatedMinutes, storyText, vocabularyDetailed, grammarDetailed, phonetics, conversationPrompts) VALUES (
180004, 90001, 'Lesson 4: At School', 'Learn school vocabulary, classroom expressions, and education topics', 4, 'en-US', 30,
'**A Day at Riverside High School**

Emily is a 16-year-old student at Riverside High School. She wakes up at 6:30 AM every weekday to get ready for school.

Her first class is English Literature with Mrs. Thompson. "Good morning, class! Today we''re going to discuss Shakespeare''s Romeo and Juliet," announces Mrs. Thompson. Emily raises her hand to answer a question. "Excellent answer, Emily!" says the teacher.

During the break, Emily meets her best friend Jake at the lockers. "Did you finish the math homework?" Jake asks nervously. "Yes, but problem number 5 was really difficult," Emily replies. They walk together to the cafeteria for lunch.

In the afternoon, Emily has Biology class in the science laboratory. The teacher, Mr. Chen, demonstrates an experiment. "Please put on your safety goggles and lab coats," he instructs. Emily and her lab partner carefully observe the chemical reaction.

After Biology, Emily goes to the library to study for tomorrow''s History test. She takes notes from her textbook and reviews the important dates. The librarian, Ms. Rodriguez, helps her find additional reference books.

At 3:30 PM, school ends. Emily has soccer practice with the school team. Coach Martinez teaches them new strategies. "Great teamwork, everyone!" he shouts encouragingly.

On her way home, Emily thinks about her day. "I love learning new things every day," she says to herself with a smile.',
'[{"word":"classroom","phonetic":"/ˈklæsruːm/","translation":"sala de aula","synonyms":["class"],"slang":"room","example":"Our classroom has 30 desks."},{"word":"homework","phonetic":"/ˈhoʊmwɜːrk/","translation":"lição de casa","synonyms":["assignment"],"slang":"hw","example":"I have a lot of homework tonight."},{"word":"textbook","phonetic":"/ˈtekstbʊk/","translation":"livro didático","synonyms":["coursebook"],"slang":"book","example":"Don''t forget your textbook."},{"word":"test","phonetic":"/test/","translation":"prova","synonyms":["exam","quiz"],"slang":"pop quiz","example":"We have a math test tomorrow."},{"word":"library","phonetic":"/ˈlaɪbreri/","translation":"biblioteca","synonyms":["media center"],"slang":"lib","example":"I study at the library."},{"word":"cafeteria","phonetic":"/ˌkæfəˈtɪriə/","translation":"refeitório","synonyms":["lunchroom","canteen"],"slang":"caf","example":"Let''s meet at the cafeteria."}]',
'[{"topic":"Present Simple for Routines","explanation":"Use present simple to describe daily school routines.","examples":["Emily wakes up at 6:30 AM.","She has English class first.","School ends at 3:30 PM."],"exercises":["Complete: I _____ (go) to school every day.","Complete: The teacher _____ (explain) the lesson."]},{"topic":"Imperatives for Instructions","explanation":"Use imperatives to give classroom instructions.","examples":["Open your books to page 45.","Please raise your hand.","Don''t talk during the test."],"exercises":["Give instruction: _____ (listen) carefully.","Give instruction: _____ (not forget) your homework."]}]',
